/**
 * Complete fixed-colour app tile with its lime foot (D143/D144), clipped to the tile radius.
 * [glyph] is sb_sign_<id> at 32 dp and above, sb_sign_<id>_small below; no tint or extra ground.
 * [product] identifies the sign; its colours are already in the drawable.
 * Legacy [withCode] only names the supplied drawable's layout: true = base, false = small. Neither
 * contains a code. The caller must pass that layout's drawable; this painter API cannot switch resources.
 * [contentDescription] = the product name, or null when the name is next to it.
 */
@Composable
@Suppress("UNUSED_PARAMETER") // product and withCode retain the existing call signature
fun SbSignTile(
    product: SebaroProduct,
    glyph: Painter,
    contentDescription: String?,
    modifier: Modifier = Modifier,
    size: Dp = SebaroTheme.tokens.x.signTileSize,
    withCode: Boolean = size >= 32.dp,
) {
    require(size > 0.dp) { "SbSignTile: edge must be positive" }
    val shape = RoundedCornerShape(size * SebaroTheme.tokens.x.signTileRadiusRatio)
    val label = if (contentDescription != null) {
        Modifier.semantics {
            this.contentDescription = contentDescription
            role = Role.Image
        }
    } else {
        Modifier
    }
    Box(
        modifier.size(size).clip(shape).then(label),
        contentAlignment = Alignment.Center,
    ) {
        Image(
            painter = glyph,
            contentDescription = null,
            modifier = Modifier.fillMaxSize(),
        )
    }
}

/**
 * The [product]'s own tile, read by its id from the app's resources: sb_sign_<id> at 32 dp and above,
 * sb_sign_<id>_small below (the product kit's two drawables). A missing drawable fails with its name.
 * [contentDescription] = the product name, or null when the name is next to it.
 */
@Composable
fun SbSignTile(
    product: SebaroProduct,
    contentDescription: String?,
    modifier: Modifier = Modifier,
    size: Dp = SebaroTheme.tokens.x.signTileSize,
) {
    val context = LocalContext.current
    val name = sbSignResourceName(product, small = size < 32.dp)
    val id = remember(name) { context.resources.getIdentifier(name, "drawable", context.packageName) }
    require(id != 0) { "SbSignTile: missing drawable $name; the product kit writes it from the product's declaration" }
    SbSignTile(product, painterResource(id), contentDescription, modifier, size, withCode = size >= 32.dp)
}

/** sb_sign_<id>[_small]: the id lower-case, every character but a–z, 0–9 and _ as _ (the product kit's rule). */
private fun sbSignResourceName(product: SebaroProduct, small: Boolean): String =
    "sb_sign_" + product.id.lowercase().replace(Regex("[^a-z0-9_]"), "_") + if (small) "_small" else ""
